"""Relatório de literatura e ensaios, com gráficos científicos do estudo."""
from pathlib import Path
import json,html
from collections import Counter
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from preparar_geometria import save

def run(resultados,referencias,entrada):
    resultados=Path(resultados);referencias=Path(referencias);entrada=Path(entrada)
    def read(path):return json.loads(Path(path).read_text(encoding='utf8'))
    old=read(entrada/'Controle_Lote_v09.json');healing=read(entrada/'Ablacao_Healing_Sem_Projecao.json')
    batch=read(resultados/'Resumo_Lote_v10.json');audit=read(resultados/'conferencia/Conferencia_Multiambientes_v10.json')
    surface=read(resultados/'auditorias/Auditoria_Interfaces_v10.json');volume=read(resultados/'auditorias/Contencao_Volumetrica_v10.json')
    literature=read(referencias/'Revisao_Literatura_v10.json');two=read(resultados/'ensaios_alternativos/Ensaio_Cortes_2D_v10.json')
    compare=read(resultados/'controles/comparacao/Comparacao_v09_v10.json')
    graph=read(resultados/'rdf_principal/Registro_RDF_Multiambientes_v10.json')
    records=[read(p) for p in (resultados/'ambientes').glob('*/Resultado_Ambiente_v10.json')]
    images=resultados/'figuras';images.mkdir(exist_ok=True)
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11,'axes.spines.top':False,'axes.spines.right':False})
    fig,axes=plt.subplots(1,2,figsize=(15,6.7),gridspec_kw={'width_ratios':[.8,1.2]})
    fig.suptitle('Notebook 1: ganho de cobertura e associações verificadas',fontsize=20,fontweight='bold')
    a=axes[0];colors=['#176e60','#b87922'];a.barh([1,0],[29,38],color=colors[0],label='Associação executada')
    a.barh([1,0],[12,3],left=[29,38],color=colors[1],label='Preparo inconclusivo')
    for y,n in [(1,29),(0,38)]:a.text(n/2,y,str(n),ha='center',va='center',color='white',weight='bold')
    for y,start,n in [(1,29,12),(0,38,3)]:a.text(start+n/2,y,str(n),ha='center',va='center',color='white',weight='bold')
    a.set_yticks([1,0],['v09','v10']);a.set_xlim(0,43);a.set_xlabel('Espaços do IFC (41)');a.set_title('Aplicação aos espaços')
    a.legend(loc='lower left',bbox_to_anchor=(-.05,-.28),frameon=False,fontsize=10)
    b=axes[1];labels=['v09','Healing, sem projeção','v10 selecionada','Cortes 2D (ensaio)']
    metrics=[old['conferencia']['totais'],healing['conferencia']['totais'],audit['totais'],two['conferencia_14_ambientes']['totais']]
    for y,(label,m) in enumerate(zip(labels,metrics)):
        tp=m['TP'];fn=m['FN'];missing=m.get('positivos_nao_recuperados_por_preparacao',m.get('positivos_sem_contorno',0))
        b.barh(y,tp,color=colors[0]);b.barh(y,fn,left=tp,color='#9b3f47');b.barh(y,missing,left=tp+fn,color=colors[1])
        for value,start in [(tp,0),(fn,tp),(missing,tp+fn)]:
            if value:b.text(start+value/2,y,str(value),ha='center',va='center',color='white',fontsize=10,weight='bold')
    b.set_yticks(range(4),labels);b.invert_yaxis();b.set_xlim(0,45);b.set_xlabel('Referências positivas da amostra (43)');b.set_title('Mesmos 14 ambientes; JA-09 fora das métricas')
    from matplotlib.patches import Patch
    b.legend(handles=[Patch(color=colors[0],label='Associação correta'),Patch(color='#9b3f47',label='Omissão após execução'),Patch(color=colors[1],label='Sem resultado por preparo')],loc='lower left',bbox_to_anchor=(-.02,-.28),frameon=False,fontsize=10)
    fig.text(.5,.025,'Amostra intencional de desenvolvimento, assistida por IA. Cortes 2D não validam sólidos ou limites 3D.',ha='center',fontsize=10)
    fig.subplots_adjust(left=.07,right=.98,bottom=.25,top=.83,wspace=.48)
    fig.savefig(images/'Comparacao_Cobertura_e_Acertos_v10.png',dpi=160);plt.close(fig)
    grouped={}
    for r in surface['faces']:
        group=grouped.setdefault(r['ambiente'],{'nome':r['nome'],'soma':0.,'uniao':0.})
        group['soma']+=r['soma_m2'];group['uniao']+=r['uniao_m2']
    top=sorted(grouped.values(),key=lambda r:r['soma']-r['uniao'],reverse=True)[:10]
    fig,ax=plt.subplots(figsize=(12,7));fig.suptitle('Área de união separada da soma de interfaces',fontsize=18,fontweight='bold')
    ax.barh(range(len(top)),[r['soma']-r['uniao'] for r in top],color='#b87922')
    ax.set_yticks(range(len(top)),[r['nome'] for r in top]);ax.invert_yaxis();ax.set_xlabel('Excesso da soma sobre a união, na mesma face (m²)')
    for k,r in enumerate(top):ax.text(r['soma']-r['uniao']+.015,k,f"{r['soma']-r['uniao']:.3f}",va='center')
    ax.set_xlim(0,max(r['soma']-r['uniao'] for r in top)*1.2)
    fig.text(.5,.025,'Dez maiores valores. Região geométrica não é peça física; paredes concorrentes permanecem registradas.',ha='center',fontsize=10)
    fig.subplots_adjust(left=.28,right=.95,top=.87,bottom=.13);fig.savefig(images/'Sobreposicao_das_Interfaces_v10.png',dpi=160);plt.close(fig)
    E=lambda x:html.escape(str(x));docs={r['id']:r for r in literature['documentos']};t=audit['totais']
    css='body{margin:0;background:#f2f5f5;color:#21313b;font:16px/1.65 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:28px 24px}section,article{background:#fff;border:1px solid #dce4e4;border-radius:8px;padding:22px 27px;margin:18px 0}h1{font-size:32px;line-height:1.2}h2{font-size:23px}h3{font-size:19px}a{color:#075b83}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:9px 11px;border-bottom:1px solid #e1e7e7;text-align:left;vertical-align:top}th{background:#ecf3f3}small{color:#52636d}img{width:100%;height:auto}summary{cursor:pointer;font-weight:600}details{padding:12px 0;border-bottom:1px solid #e1e7e7}input{width:95%;font:inherit;padding:12px;border:1px solid #b6c8ca;border-radius:6px}.focus{border-left:5px solid #176e60}.warn{border-left:5px solid #b87922}code{overflow-wrap:anywhere}nav a{margin-right:20px}.scroll{overflow-x:auto}li{margin:8px 0}'
    doc='<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Literatura e aprimoramento do Notebook 1 v10</title><style>'+css+'</style><main><h1>Literatura, ensaios e aprimoramento do Notebook 1</h1><p>CIV2155 · FNDE Tipo 2 R03 · 30 de outubro de 2026 · v10</p><nav><a href="#resultado">Resultados</a><a href="#metodos">Métodos selecionados</a><a href="#testes">Testes</a><a href="#acervo">57 documentos</a><a href="#limites">Limitações</a></nav>'
    doc+='<section class="focus" id="resultado"><h2>O ganho efetivamente medido</h2><p>O preparo e a associação passaram de <b>29 para 38 espaços</b>, dos 41 existentes. Os 12 inconclusivos anteriores foram reduzidos a três: Infantil 1, Infantil 5 e Amamentação. Os 457 recortes de parede foram preparados, incluindo os quatro anteriormente inconclusivos.</p><p>As <b>74 associações anteriores foram preservadas</b>; a v10 registrou 101 pares ambiente–esquadria, com 66 esquadrias distintas. Pares não equivalem a peças físicas: uma porta pode ser associada a dois ambientes. Os 29 BReps anteriormente aceitos permanecem idênticos por hash.</p><p>Na <b>mesma referência documental de 14 ambientes</b>, os positivos confirmados passaram de 35 para 39. A recuperação, incluindo falhas de preparo, passou de 35/43 (81,4%) para 39/43 (90,7%). Entre os negativos avaliados, houve 37 exclusões corretas e nenhuma associação indevida. Outros dois dos 39 negativos conhecidos permaneceram não avaliáveis por preparo. Continua havendo uma omissão após execução e três positivos sem resultado por preparo. A JA-09 permanece indeterminada.</p><img src="figuras/Comparacao_Cobertura_e_Acertos_v10.png" alt="Comparação de cobertura e acertos"><p><b>Interpretação:</b> existe ganho real no mesmo modelo e na mesma amostra, sem evidência de perda dos resultados anteriores. Não é validação externa ou prova de completude de todas as 101 associações.</p></section>'
    doc+='<section><h2>Como o acervo inteiro foi avaliado</h2><p>Inventário inicial: 73 PDFs, 63 conteúdos distintos por SHA-256. Seis conteúdos são pranchas do projeto e 57 são documentos bibliográficos/técnicos, incluindo manuais e documentação. As cópias idênticas não foram contadas como novos estudos. Cinquenta e dois conteúdos já tinham registro em catálogos anteriores; os hashes foram conferidos e a utilidade foi reavaliada contra a v09.</p><p>Foi feita triagem de todo o acervo e leitura dirigida dos métodos, pressupostos, exemplos e limitações prioritários. As figuras e fórmulas relevantes de Fichter, Ying/Lee, Lilis, Ciria e XeoBIM foram conferidas visualmente. Não se afirma leitura linear das 1.258 páginas nem reprodução de todos os experimentos dos 57 documentos. As sete análises abaixo concentram as decisões e os ensaios desta revisão.</p><p>A seleção procurou resolver falhas efetivamente observadas, conservar identidades e evidências, permitir implementação verificável e acrescentar validação. Bibliotecas citadas em um artigo não foram tratadas como código completo dos autores. Identificação e disponibilidade também foram conferidas, quando necessário, em fontes primárias de editoras, instituições e repositórios.</p></section>'
    doc+='<section id="metodos"><h2>Métodos selecionados e função efetiva</h2>'
    for a in literature['analises_aprofundadas']:
        src=docs[a['id']];doi=(' · <a href="https://doi.org/'+E(src['doi'])+'">Publicação</a>') if src['doi'] else ''
        doc+='<article><h3>'+E(a['id']+' · '+a['titulo'])+'</h3><p><b>'+E(src['autoria']+' ('+str(src['ano'])+')')+'</b> · '+E(src['titulo'])+doi+'</p><small>Passagens de apoio: páginas '+E(a['paginas'])+' do PDF.</small>'
        for label,key in [('Gargalo observado','diagnostico'),('Adaptação','implementacao'),('Ensaio e decisão','ensaio'),('Limite da contribuição','limite')]:doc+='<p><b>'+label+':</b> '+E(a[key])+'</p>'
        doc+='</article>'
    doc+='</section>'
    doc+='<section><h2>Alternativas que não substituíram o núcleo</h2><p><b>Ciria e Diaz de Garayo (R18):</b> grafo de paredes e reconstrução de zonas são alternativas relevantes, mas identificar zonas reconstruídas não resolve automaticamente a correspondência com os IfcSpace, seus usos e GUIDs. A agregação térmica de pequenos espaços pode apagar distinções arquitetônicas importantes. Não foi selecionado para substituir o grafo de ambientes existente.</p><p><b>Lilis por volumes de espaços/aberturas (R19) e CBIP (R20):</b> suas pré-condições continuam relevantes. O conjunto ampliado tem 23 pares de espaços sobrepostos; preparar volumes válidos individualmente não os torna livres de interseção. Foram preservados os controles parciais anteriores, sem declarar execução do fluxo completo desses artigos.</p><p><b>Krijnen/CGAL (R26):</b> a formalização por tolerância continua como referência e os ensaios anteriores permanecem preservados. O protótipo do artigo gera primeiro nível e não implementa o tratamento completo de portas/janelas. Não haveria base para prometer que apenas trocar o kernel fecharia os três espaços restantes. A faixa exploratória de 20 mm usada para diagnóstico de folgas não é a precisão IFC nem o predicado CGAL dos autores.</p><p><b>IA e troca de banco de grafos:</b> LangGraph, BERT, LLMs e Neo4j podem apoiar consulta e alinhamento semântico, mas não constituem prova geométrica ou reparação dos BReps. Não foram usados para inventar associações ausentes.</p></section>'
    doc+='<section id="testes"><h2>Testes executados e comparação pareada</h2><table><tr><th>Conjunto</th><th>Controles</th><th>O que demonstra</th></tr>'
    for name,n,meaning in [('Operadores IFC2SB, Kiavarz e Lilis',54,'Casos analíticos e comparação C++ parcial preservados'),('Regressão da cozinha',5,'Mesmas esquadrias, interfaces, internos, componentes e área'),('Generalização',6,'GUIDs, isolamento, parâmetros e ausência de zero falso'),('Novas contraprovas geométricas',16,'Sem tampão/caixa; guarda contra deslocamento; folgas numéricas; sala U; vazios e balanço de área'),('Contratos SHACL',13,'Casos válidos e violações deliberadas'),('Comparação v09/v10',12,'Preservação dos 29 BReps, dos 74 pares, dos denominadores e da proveniência')]:doc+=f'<tr><td>{E(name)}</td><td>{n}</td><td>{E(meaning)}</td></tr>'
    doc+='<tr><th>Total</th><th>106</th><th>Controles aprovados; não são 106 casos arquitetônicos independentes</th></tr></table><p>Além desses controles, foram executados os lotes de todos os espaços, ablação de healing sem projeção, ensaio 2D, 703 comparações volumétricas entre espaços, partição das interfaces, tentativa de confirmação volumétrica dos 27 candidatos e validação SHACL do grafo completo. A versão final é reexecutada em novo kernel no Notebook 1.</p><p><b>Ablação:</b> somente healing deu 38 positivos; acrescentar normalização planar deu 39. O ensaio 2D produziu contornos nos 41 espaços, mas somente 33 positivos. Isso demonstra por que obter alguma saída para todos os espaços não basta como critério de adoção.</p><p><a href="controles/comparacao/Comparacao_v09_v10.json">Comparação pareada</a> · <a href="conferencia/Conferencia_Caso_a_Caso_v10.csv">Conferência por caso</a> · <a href="validacao/Validacao_SHACL_v10.json">Validação RDF</a></p></section>'
    doc+='<section><h2>Validação geométrica acrescentada</h2><p>Foram registradas '+E(graph['interfaces_registradas'])+' interfaces e '+E(surface['regioes_particionadas'])+' regiões de união em '+E(surface['faces_auditadas'])+' faces auditadas. As regiões não são novos elementos construtivos. A soma de áreas é '+f"{surface['soma_areas_m2']:.3f}"+' m² e a união por face é '+f"{surface['area_uniao_m2']:.3f}"+' m²: diferença de '+f"{surface['soma_areas_m2']-surface['area_uniao_m2']:.3f}"+' m² que não deve ser contabilizada repetidamente como área geométrica única. Isso não define sozinho o quantitativo físico de paredes.</p><img src="figuras/Sobreposicao_das_Interfaces_v10.png" alt="Diferenças entre soma e união"><p>Há hospedeiros concorrentes em 28 espaços. O código conserva as fontes e não escolhe a parede correta por conveniência. O maior erro de balanço por face foi '+f"{surface['maior_erro_balanco_m2']:.3g}"+' m².</p><p>Os 27 pares de candidatos internos permaneceram inconclusivos na confirmação volumétrica, por falta de operandos sólidos adequados. Não foram convertidos em contenções confirmadas por bounding box. O grafo v10 tem '+E(graph['triplas_uniao_v10'])+' triplas e preserva integralmente a base v09 de '+E(graph['triplas_base_v09'])+' triplas.</p></section>'
    doc+='<section id="limites" class="warn"><h2>O que permanece sem solução</h2><p><b>Infantil 1, Infantil 5 e Amamentação:</b> as cascas não fecharam dentro dos limites aceitos. O código não inventou faces para aprová-las.</p><p><b>JA-04 da Administração:</b> a rotina geral de diagnóstico de folgas encontrou projeção relevante a aproximadamente 10 mm da face R09. O limiar primário continua 0,1 mm. O par foi mantido como candidato com folga e contabilizado como omissão na referência, sem promoção automática.</p><p><b>Geometria concorrente:</b> 23 pares de espaços sobrepostos e recortes rejeitados por saírem do contorno parental continuam registrados. Encontrar um sólido válido não elimina conflitos entre sólidos. A v10 apresenta 32 associações executadas sem pendências registradas nesse recorte e seis com pendências; esses estados não certificam completude arquitetônica.</p><p><b>Avaliação:</b> a amostra de 14 ambientes é intencional, assistida por IA e usada no desenvolvimento. Não houve revisão cega de especialista, outro edifício ou conferência exaustiva das 101 associações/3.011 interfaces. As referências positivas não recuperadas e o conflito documental JA-09 permanecem nos resultados. Não se afirma acurácia de 100% ou ganho de velocidade generalizável.</p></section>'
    doc+='<section><h2>Cobertura de todos os 41 espaços</h2><div class="scroll"><table><tr><th>Espaço</th><th>Estado</th><th>Esquadrias</th><th>Motivo ou preparo</th></tr>'
    for r in sorted(records,key=lambda x:(x['nome'],x['ambiente'])):
        method=(r.get('preparacao_geometrica') or {}).get('metodo_v10',r.get('motivo',''))
        doc+='<tr><td>'+E(r['nome'])+'<br><small>'+E(r['ambiente'])+'</small></td><td>'+E(r['estado'])+'</td><td>'+E(r['resumo']['esquadrias'] if r['resumo']['esquadrias'] is not None else 'indisponível')+'</td><td>'+E(method)+'</td></tr>'
    doc+='</table></div></section>'
    doc+='<section id="acervo"><h2>Decisão sobre cada um dos 57 documentos</h2><p>Busca por título, autor, assunto ou decisão. Expanda uma entrada para consultar sua contribuição e seus limites. Os caminhos são relativos à pasta original 01_Referencias; os PDFs originais não foram editados.</p><input id="busca" type="search" placeholder="Filtrar o acervo" aria-label="Filtrar documentos">'
    for r in literature['documentos']:
        link='<a href="https://doi.org/'+E(r['doi'])+'">DOI/publicação</a>' if r['doi'] else ''
        doc+='<details class="documento"><summary>'+E(r['id']+' · '+r['titulo'])+'</summary><p><b>'+E(r['autoria']+' · '+str(r['ano']))+'</b> · '+E(r['paginas'])+' páginas · '+E(r['decisao_v10'])+'</p><p><b>Decisão para o código:</b> '+E(r['avaliacao_para_codigo'])+'</p><p><b>Contribuição do documento:</b> '+E(r['contribuicao_bibliografica'])+'</p><p><b>Limites:</b> '+E(r['limites_bibliograficos'])+'</p><p>'+link+'</p><small>Arquivo: '+E(r['arquivo_relativo'])+'<br>SHA-256: '+E(r['sha256'])+'<br>Cópias idênticas: '+E(len(r['copias_identicas']))+'</small></details>'
    doc+='</section><section><h2>Fontes técnicas e atribuição</h2><ul>'
    for f in literature['fontes_tecnicas']:doc+='<li><a href="'+E(f['url'])+'">'+E(f['titulo'])+'</a></li>'
    doc+='</ul><p>Licenças e atribuição dos fontes IFC2SB foram mantidas. Orquestração, guardas, projeção controlada, partição, shapes e comparação são adaptações do estudo. Repositório ou biblioteca citados em um artigo não foram apresentados como código completo dos autores.</p></section></main><script>document.getElementById("busca").addEventListener("input",function(){let q=this.value.toLocaleLowerCase("pt-BR");document.querySelectorAll(".documento").forEach(x=>x.hidden=!x.textContent.toLocaleLowerCase("pt-BR").includes(q))})</script></html>'
    (resultados/'Relatorio_Literatura_e_Ensaios_v10.html').write_text(doc,encoding='utf8')
    save(resultados/'Resumo_Comparativo_v10.json',{'espacos_v09':29,'espacos_v10':38,'pares_v09':74,'pares_v10':101,'documental_v09':old['conferencia']['totais'],'documental_v10':t,'controles':106,'literatura_documentos':57,'grafo_triplas':graph['triplas_uniao_v10']})
    print('Relatório e duas figuras gerados.',flush=True)
